program.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [x['id'] for x in group]
        if valid(ids):
            result = ids
            break
    if result:
        break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if not valid(selection):
        status('report')
else:
    write('/output/selection', result)
    selection = result
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

